files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff5c77;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #2a3a5e;
  --radius: 0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: none;
}

label, legend {
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input[type="number"] {
  font-family: inherit;
  font-size: 1.25rem;
  padding: 12px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: var(--radius);
  outline: none;
  width: 100%;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.tip-buttons {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.tip-btn {
  flex: 1 1 0;
  min-width: 80px;
  font-family: inherit;
  font-size: 1.125rem;
  padding: 12px 8px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
}

.tip-btn:hover {
  background: var(--accent-hover);
  color: #fff;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  box-shadow: inset 0 0 0 2px #000;
}

.results {
  border-top: 4px solid var(--border);
  padding-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 1.125rem;
}

.result-label {
  color: var(--muted);
}

.result-value {
  font-weight: bold;
  color: var(--text);
}

.result-row.total .result-value {
  color: var(--accent);
  font-size: 1.5rem;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    border-width: 3px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .tip-btn {
    font-size: 1rem;
    padding: 10px 4px;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = document.querySelectorAll('.tip-btn');
  var tipPerPersonEl = document.getElementById('tipPerPerson');
  var totalPerPersonEl = document.getElementById('totalPerPerson');

  var selectedTip = 15;

  function setActiveTip(percent) {
    selectedTip = percent;
    tipButtons.forEach(function (btn) {
      var isActive = Number(btn.dataset.tip) === percent;
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
  }

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    if (isNaN(bill) || bill < 0) bill = 0;

    var people = parseInt(peopleInput.value, 10);
    if (isNaN(people) || people < 1) people = 1;

    var tipTotal = bill * (selectedTip / 100);
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = (bill + tipTotal) / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setActiveTip(Number(btn.dataset.tip));
      calculate();
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  setActiveTip(selectedTip);
  calculate();
})();
